import django.db.models.deletion
from django.db import migrations, models


def split_names(apps, schema_editor):
    """
    Move the vacation chart names out of the planning names table.
    ---
    Hasta ahora el cuadrante apuntaba sus nombres en la tabla del planning
    (crane_albaranes.PlanningName). Se copian todos aquí y en la del
    planning se quedan solo los que salen en algún servicio del planning.
    """
    import re
    import unicodedata

    planning_name = apps.get_model("crane_albaranes", "PlanningName")
    planning_service = apps.get_model("crane_albaranes", "PlanningService")
    chart_name = apps.get_model("hr_calendar", "VacationChartName")

    def plain(text):
        text = unicodedata.normalize("NFKD", str(text or "")).encode(
            "ascii", "ignore").decode().lower()
        return re.sub(r"[^a-z0-9]+", " ", text).strip()

    for name in planning_name.objects.all():
        chart_name.objects.get_or_create(
            company_id=name.company_id, key=name.key, defaults={
                "text": name.text, "person_id": name.person_id,
                "not_a_worker": name.not_a_worker,
                "seen_from": name.seen_from, "seen_to": name.seen_to,
                "updated_by_id": name.updated_by_id})
    used = {}
    for company_id, raw in planning_service.objects.exclude(
            raw_person="").values_list("company_id", "raw_person"):
        used.setdefault(company_id, set()).add(plain(raw))
    for name in planning_name.objects.all():
        if name.key not in used.get(name.company_id, set()):
            name.delete()


